<?php require '../config.php';$uid=require_login();$d=body();if(!hash_equals(csrf(),$d['csrf']??''))json_response(['error'=>'CSRF'],419);$id=(int)($d['game']??0);$s=db()->prepare('SELECT g.*,(SELECT COUNT(*) FROM questions WHERE quiz_id=g.quiz_id) total FROM games g WHERE id=? AND host_user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();$g=$s->get_result()->fetch_assoc();if(!$g)json_response(['error'=>'Unauthorized'],403);
if($g['status']==='lobby'){$next=1;$status='question';$s=db()->prepare('UPDATE games SET status=?,current_question=?,question_started_at=NOW(3) WHERE id=?');$s->bind_param('sii',$status,$next,$id);$s->execute();}
elseif($g['status']==='question'){$status='results';$s=db()->prepare('UPDATE games SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();}
elseif($g['status']==='results'){if($g['current_question'] >= $g['total']){$status='finished';$s=db()->prepare('UPDATE games SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();}else{$next=$g['current_question']+1;$status='question';$s=db()->prepare('UPDATE games SET status=?,current_question=?,question_started_at=NOW(3) WHERE id=?');$s->bind_param('sii',$status,$next,$id);$s->execute();}}
json_response(['ok'=>true]);

